import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.e4u2V5E7.js";const g=JSON.parse('{"title":"v1.2 Release Notes","description":"Enterprise Skills Expansion — 67 to 112 production skills","frontmatter":{"title":"v1.2 Release Notes","description":"Enterprise Skills Expansion — 67 to 112 production skills"},"headers":[],"relativePath":"release-notes/v1.2.md","filePath":"release-notes/v1.2.md","lastUpdated":1784581375000}'),i={name:"release-notes/v1.2.md"};function a(s,t,n,l,c,h){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="v1-2-0-release-notes" tabindex="-1">v1.2.0 Release Notes <a class="header-anchor" href="#v1-2-0-release-notes" aria-label="Permalink to &quot;v1.2.0 Release Notes&quot;">​</a></h1><p><strong>Release Date:</strong> 2026-07-20 <strong>Status:</strong> Stable</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>v1.2 transforms the workspace from a general-purpose AI engineering toolkit into a comprehensive enterprise platform. The skill count grew from 67 to 112 production skills (+67%), with 7 additional optional skills in staging.</p><h2 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h2><h3 id="enterprise-skills-expansion-67-→-112" tabindex="-1">Enterprise Skills Expansion (67 → 112) <a class="header-anchor" href="#enterprise-skills-expansion-67-→-112" aria-label="Permalink to &quot;Enterprise Skills Expansion (67 → 112)&quot;">​</a></h3><div class="mermaid">graph LR subgraph Skill Growth A[v1.0: 66] --&gt; B[v1.1: 67] B --&gt; C[v1.2: 112] end subgraph Enterprise Coverage D[Before: 24%] --&gt; E[After: 42%] end style C fill:#4CAF50,color:#fff style E fill:#2196F3,color:#fff </div><h3 id="_2-new-native-enterprise-skills" tabindex="-1">2 New Native Enterprise Skills <a class="header-anchor" href="#_2-new-native-enterprise-skills" aria-label="Permalink to &quot;2 New Native Enterprise Skills&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Skill</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ai-context-optimization</code></td><td>Maximize useful context inside limited context windows — budgeting, prioritization, compression, multi-agent sharing</td></tr><tr><td><code>ai-prompt-compression</code></td><td>Optimize prompts without reducing reasoning quality — semantic compression, token reduction, cost optimization</td></tr></tbody></table><h3 id="_15-enterprise-gap-skills" tabindex="-1">15 Enterprise Gap Skills <a class="header-anchor" href="#_15-enterprise-gap-skills" aria-label="Permalink to &quot;15 Enterprise Gap Skills&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Skill</th><th>Domain</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ai-guardrails</code></td><td>AI</td><td>Production AI safety — input/output validation, content moderation, prompt injection defense</td></tr><tr><td><code>model-routing</code></td><td>AI</td><td>Model selection — cost/quality/latency trade-offs, fallback chains, A/B testing</td></tr><tr><td><code>llm-evaluation</code></td><td>AI</td><td>LLM evaluation frameworks — benchmarks, metrics, regression testing</td></tr><tr><td><code>ai-cost-optimization</code></td><td>AI</td><td>Token budgeting, caching, model tiering, cost monitoring</td></tr><tr><td><code>domain-driven-design</code></td><td>Architecture</td><td>Bounded contexts, aggregates, domain events, TypeScript patterns</td></tr><tr><td><code>system-design-patterns</code></td><td>Architecture</td><td>Circuit Breaker, Saga, CQRS, Event Sourcing, Outbox, Service Mesh</td></tr><tr><td><code>graphql</code></td><td>Backend</td><td>Schema design, resolvers, N+1, subscriptions, federation</td></tr><tr><td><code>opentelemetry</code></td><td>Observability</td><td>OTel SDK, traces/metrics/logs export, auto-instrumentation</td></tr><tr><td><code>distributed-tracing</code></td><td>Observability</td><td>W3C Trace Context, spans, cross-service tracing, trace-log linking</td></tr><tr><td><code>metrics-engineering</code></td><td>Observability</td><td>RED/USE methods, custom metrics, dashboards, Prometheus + Grafana</td></tr><tr><td><code>audit-logging</code></td><td>Security</td><td>Audit trails, compliance logging (SOC2, GDPR), tamper-proof logging</td></tr><tr><td><code>zero-trust</code></td><td>Security</td><td>Identity verification, micro-segmentation, mTLS, ZTNA</td></tr><tr><td><code>feature-flags</code></td><td>DevOps</td><td>Flag systems, gradual rollouts, kill switches, A/B testing</td></tr><tr><td><code>deployment-strategies</code></td><td>DevOps</td><td>Canary, blue/green, rollback strategies, smoke tests</td></tr><tr><td><code>platform-engineering</code></td><td>Platform</td><td>IDP concepts, developer experience, golden paths</td></tr></tbody></table><h3 id="_4-new-skill-categories" tabindex="-1">4 New Skill Categories <a class="header-anchor" href="#_4-new-skill-categories" aria-label="Permalink to &quot;4 New Skill Categories&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Skills Added</th></tr></thead><tbody><tr><td>Platform Engineering</td><td><code>platform-engineering</code></td></tr><tr><td>Marketing</td><td><code>copywriting</code>, <code>marketing-psychology</code>, <code>content-strategy</code></td></tr><tr><td>Utility</td><td><code>find-skills</code>, <code>extract-design-system</code>, <code>pdf</code>, <code>teach</code></td></tr><tr><td>Process</td><td><code>prototype</code>, <code>to-tickets</code>, <code>diagnosing-bugs</code>, <code>browser-use</code></td></tr></tbody></table><hr><h2 id="skills-replaced" tabindex="-1">Skills Replaced <a class="header-anchor" href="#skills-replaced" aria-label="Permalink to &quot;Skills Replaced&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Old Skill</th><th>New Skill</th><th>Reason</th></tr></thead><tbody><tr><td><code>vercel-deployment</code></td><td><code>deploy-to-vercel</code></td><td>Strictly superior: monorepos, preview envs, rollbacks, edge functions</td></tr><tr><td><code>mcp-integration</code></td><td><code>mcp-builder</code></td><td>Strictly superior: practical setup, Python + Node/TS, server creation</td></tr><tr><td><code>debug</code></td><td><code>diagnosing-bugs</code></td><td>Strictly superior: structured diagnosis loop, performance regressions</td></tr></tbody></table><h2 id="skills-merged" tabindex="-1">Skills Merged <a class="header-anchor" href="#skills-merged" aria-label="Permalink to &quot;Skills Merged&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source → Target</th><th>What Was Absorbed</th></tr></thead><tbody><tr><td><code>typography-systems</code> → <code>design-systems</code></td><td>Type scale, font pairing, responsive type</td></tr><tr><td><code>owasp-top-10</code> → <code>security-audit</code></td><td>OWASP Top 10 checklist and mitigations</td></tr><tr><td><code>tdd</code> → <code>testing-strategy</code></td><td>Red→green→refactor workflow</td></tr><tr><td><code>verification-before-completion</code> → <code>code-review-standards</code></td><td>Evidence-before-claims verification</td></tr><tr><td><code>improve-codebase-architecture</code> → <code>clean-architecture</code></td><td>Architecture assessment patterns</td></tr><tr><td><code>frontend-design</code> → <code>design-taste-frontend</code></td><td>UX design fundamentals</td></tr></tbody></table><h2 id="skills-enhanced" tabindex="-1">Skills Enhanced <a class="header-anchor" href="#skills-enhanced" aria-label="Permalink to &quot;Skills Enhanced&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Enhancement</th></tr></thead><tbody><tr><td><code>context-engineering</code></td><td>Hierarchical context, caching strategies, quality evaluation</td></tr><tr><td><code>prompt-engineering</code></td><td>Chaining, versioning, eval-driven optimization</td></tr><tr><td><code>monitoring-observability</code></td><td>Three pillars, SLOs/SLIs, error budgets, runbooks</td></tr><tr><td><code>structured-logging</code></td><td>Log aggregation, PII redaction, log-based alerting</td></tr><tr><td><code>authorization-patterns</code></td><td>ABAC, hierarchical RBAC, permission caching</td></tr><tr><td><code>background-jobs</code></td><td>BullMQ/Redis, dead letter queues, event-driven patterns</td></tr></tbody></table><hr><h2 id="skills-deleted" tabindex="-1">Skills Deleted <a class="header-anchor" href="#skills-deleted" aria-label="Permalink to &quot;Skills Deleted&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>Reason</th></tr></thead><tbody><tr><td>17 × <code>lark-*</code></td><td>Off-scope proprietary Chinese platform</td></tr><tr><td><code>web-design-guidelines</code></td><td>Single URL fetch — not a skill</td></tr><tr><td><code>remotion-best-practices</code></td><td>Generic React advice, no unique knowledge</td></tr><tr><td><code>agent-browser</code></td><td>Hidden skill, <code>browser-use</code> is superior</td></tr><tr><td><code>theme-factory</code></td><td>6 bullet points — not a skill</td></tr><tr><td><code>grill-me</code>, <code>grill-with-docs</code></td><td>Off-scope interview skills</td></tr><tr><td><code>research</code>, <code>handoff</code></td><td>Too thin (9-16 lines)</td></tr><tr><td><code>orchestration</code></td><td>Tightly coupled to Orca system</td></tr><tr><td><code>using-superpowers</code></td><td>Meta-skill, not engineering knowledge</td></tr><tr><td><code>simple</code></td><td>Too thin (34 lines)</td></tr><tr><td><code>para-memory-files</code></td><td>Redundant with workspace-memory</td></tr><tr><td><code>media-use</code></td><td>Tightly coupled to HyperFrames</td></tr><tr><td><code>solid-principles</code></td><td>Absorbed into <code>clean-architecture</code></td></tr><tr><td><code>screen-reader-patterns</code></td><td>Absorbed into <code>wcag-checklist</code></td></tr><tr><td><code>gallery-management</code></td><td>Empty directory</td></tr><tr><td><code>ai-hair-tryon</code></td><td>Placeholder — never implemented</td></tr></tbody></table><hr><h2 id="component-count-changes" tabindex="-1">Component Count Changes <a class="header-anchor" href="#component-count-changes" aria-label="Permalink to &quot;Component Count Changes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>v1.1</th><th>v1.2</th><th>Change</th></tr></thead><tbody><tr><td>Production skills</td><td>67</td><td>112</td><td>+45 (+67%)</td></tr><tr><td>Optional skills</td><td>0</td><td>7</td><td>+7</td></tr><tr><td>Skill categories</td><td>16</td><td>20</td><td>+4</td></tr><tr><td>Enterprise domain skills</td><td>27</td><td>51</td><td>+24 (+89%)</td></tr><tr><td>Enterprise coverage</td><td>24%</td><td>42%</td><td>+18%</td></tr><tr><td>Global agents</td><td>21</td><td>21</td><td>0</td></tr><tr><td>Global commands</td><td>17</td><td>17</td><td>0</td></tr><tr><td>Broken references</td><td>5</td><td>0</td><td>-5</td></tr><tr><td>Orphan skills</td><td>5</td><td>0</td><td>-5</td></tr></tbody></table><hr><h2 id="upgrade-notes" tabindex="-1">Upgrade Notes <a class="header-anchor" href="#upgrade-notes" aria-label="Permalink to &quot;Upgrade Notes&quot;">​</a></h2><ul><li>No breaking changes to existing skills</li><li><code>vercel-deployment</code>, <code>mcp-integration</code>, and <code>debug</code> are removed — update any references</li><li><code>solid-principles</code> content merged into <code>clean-architecture</code></li><li>New skills load on-demand via <code>@skill</code> tool — no configuration needed</li><li>MANIFEST.md, AGENTS.md, DEPENDENCIES.md all updated for v1.2</li></ul><hr><h2 id="known-issues" tabindex="-1">Known Issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known Issues&quot;">​</a></h2><ul><li>7 optional skills in staging require external CLI tools (<code>belt</code>, HyperFrames)</li><li>Some Azure skills reference Azure-specific services not available in all environments</li><li>Marketing skills are new to the workspace — may need refinement based on usage</li></ul><hr><h2 id="v1-3-roadmap" tabindex="-1">v1.3 Roadmap <a class="header-anchor" href="#v1-3-roadmap" aria-label="Permalink to &quot;v1.3 Roadmap&quot;">​</a></h2><ul><li>Multi-agent orchestration patterns</li><li>Production RAG implementation guide</li><li>API security hardening</li><li>Alerting engineering</li><li>Visual regression testing</li><li>Advanced prompt engineering patterns</li><li>Plugin system for custom tools</li></ul><hr><p><em>Released by Ahmed Hassaan — 2026-07-20</em></p>',37)])])}const u=e(i,[["render",a]]);export{g as __pageData,u as default};
